"""Standalone real-run report with selectable traces and evidence links."""
from common13 import *
import html

def render(out,data):
 cases=[]
 for name,r in data.get('cases',{}).items():
  p=out/name;tr=read(p/'tracking.json') if (p/'tracking.json').exists() else {};g=rows(p/'gate.jsonl');ob=rows(p/'online/observations.jsonl');en=[x for x in ob if x['record_type']=='encoders'];me=[x for x in ob if x['record_type']=='metrics'];cases.append(dict(name=name,metrics=r,trace=tr,signals=dict(v=[[x['t'],x['v']] for x in g[::5]],w=[[x['t'],x['w']] for x in g[::5]],steer=[[x['t'],x['q'][2]] for x in en[::5] if len(x['q'])==4],compute=[[x['t'],x['compute_ms']] for x in me[::3]])))
 payload=json.dumps(cases,ensure_ascii=False).replace('</','<\\/');rows_html=''.join('<tr><td>'+html.escape(k)+'</td><td>'+html.escape(str(v))+'</td></tr>' for k,v in data.get('checks',{}).items());title=html.escape(data['status']);detail=html.escape(data.get('error','实际传感器、物理底盘和 Nav2 动作；人工视觉验收尚未确认。'))
 page='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>S13 真实导航验收</title><style>body{font:16px system-ui;max-width:1200px;margin:30px auto;background:#f5f7fa;color:#172736}article{padding:20px;background:white;border-radius:12px;margin:16px 0}svg{background:#eef3f6;width:100%;height:350px}table{border-collapse:collapse}td,th{border:1px solid #cbd3dc;padding:7px}pre{white-space:pre-wrap;max-height:420px;overflow:auto}a{color:#075daf}select,button{font:inherit;padding:8px}small{color:#516075}</style><h1>S13 · Nav2 真实闭环</h1><p>STATUS: STATUS_VALUE</p><p>DETAIL_VALUE</p><p>短段控制器验收；工具 OFF、有效作业量 0。整簇作业与完整道路未验收。</p><article><table>CHECK_ROWS</table></article><article><label>选择实际案例 <select id="case"></select></label> <a id="raw">原始指标 JSON</a><h2>轨迹：蓝色计划 / 红色独立物理真值</h2><svg id="trajectory" viewBox="0 0 900 350"></svg><p id="measure"></p></article><article><label>时间曲线 <select id="signal"><option value="v">出口速度 m/s</option><option value="w">出口角速度 rad/s</option><option value="steer">实测左转角 rad</option><option value="compute">控制器计算 ms</option></select></label><svg id="series" viewBox="0 0 900 350"></svg></article><article><h2>动作、停止与检查点</h2><div id="photos"></div><pre id="details"></pre></article><script>const cases=PAYLOAD;let ci=0;const sel=document.querySelector('#case');for(let i=0;i<cases.length;i++){let o=document.createElement('option');o.value=i;o.textContent=cases[i].name;sel.append(o)}
function plot(id,series){let svg=document.querySelector(id);svg.innerHTML='';let all=series.flatMap(s=>s.p);if(!all.length){svg.innerHTML='<text x="20" y="40">NOT_RUN / 无可绘制的实测数据</text>';return}let xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmax-xmin<.01)xmax=xmin+1;if(ymax-ymin<.01)ymax=ymin+1;const equal=id==='#trajectory',scale=Math.min(810/(xmax-xmin),270/(ymax-ymin));const X=x=>equal?450+(x-(xmin+xmax)/2)*scale:45+810*(x-xmin)/(xmax-xmin),Y=y=>equal?180-(y-(ymin+ymax)/2)*scale:315-270*(y-ymin)/(ymax-ymin);for(let s of series){let p=document.createElementNS('http://www.w3.org/2000/svg','polyline');p.setAttribute('fill','none');p.setAttribute('stroke',s.color);p.setAttribute('stroke-width',2);p.setAttribute('points',s.p.map(q=>X(q[0])+','+Y(q[1])).join(' '));svg.append(p)}svg.innerHTML+=`<text x="45" y="340">x: ${xmin.toFixed(2)} … ${xmax.toFixed(2)}   y: ${ymin.toFixed(3)} … ${ymax.toFixed(3)}</text>`}
function draw(){if(!cases.length)return;let c=cases[ci],m=c.metrics;plot('#trajectory',[{color:'#176dd3',p:(c.trace.reference||[]).map(x=>x.slice(0,2))},{color:'#c93738',p:c.trace.actual||[]}]);plot('#series',[{color:'#176dd3',p:c.signals[document.querySelector('#signal').value]}]);document.querySelector('#measure').textContent=`完成 ${m.completed} | 跟踪 P95 ${m.tracking_p95_m} m | 最大 ${m.tracking_max_m} m | 停车 ${m.max_stop_delay_s} s | 计算 P95 ${m.compute_p95_ms} ms`;document.querySelector('#raw').href=c.name+'/metrics.json';document.querySelector('#details').textContent=JSON.stringify(m,null,2);document.querySelector('#photos').innerHTML='';for(let p of m.checkpoints||[]){if(p.image_file){let im=document.createElement('img');im.src=c.name+'/client/'+p.image_file;im.alt=p.label;im.style.width='240px';document.querySelector('#photos').append(im)}}}
sel.onchange=()=>{ci=+sel.value;draw()};document.querySelector('#signal').onchange=draw;draw();</script></html>'''
 if data.get('near_field_check'):page=page.replace('<article><table>', '<article><p>近距低障碍补充检查：'+html.escape(str(data['near_field_check']['passed']))+' · <a href="near_field_obstacle/sensor_metrics.json">独立测量</a></p></article><article><table>',1)
 for a,b in [('STATUS_VALUE',title),('DETAIL_VALUE',detail),('CHECK_ROWS',rows_html),('PAYLOAD',payload)]:page=page.replace(a,b)
 (out/'index.html').write_text(page)
